sealed class VaultException: kotlin.Exception() {
    
    class Kdf(
        ) : VaultException() {
        override val message
            get() = ""
    }
    
    class Encrypt(
        ) : VaultException() {
        override val message
            get() = ""
    }
    
    class Decrypt(
        ) : VaultException() {
        override val message
            get() = ""
    }
    
    class InvalidSecretKey(
        ) : VaultException() {
        override val message
            get() = ""
    }
    
    class Malformed(
        ) : VaultException() {
        override val message
            get() = ""
    }
    
    class InvalidOptions(
        ) : VaultException() {
        override val message
            get() = ""
    }
    
    class NotFound(
        
        val v1: kotlin.String
        ) : VaultException() {
        override val message
            get() = "v1=${ v1 }"
    }
    
    class Io(
        
        val v1: kotlin.String
        ) : VaultException() {
        override val message
            get() = "v1=${ v1 }"
    }
    
    class Json(
        
        val v1: kotlin.String
        ) : VaultException() {
        override val message
            get() = "v1=${ v1 }"
    }
    

    companion object ErrorHandler : UniffiRustCallStatusErrorHandler<VaultException> {
        override fun lift(error_buf: RustBuffer.ByValue): VaultException = FfiConverterTypeVaultError.lift(error_buf)
    }

    
}

/**
 * @suppress
 */
public object FfiConverterTypeVaultError : FfiConverterRustBuffer<VaultException> {
    override fun read(buf: ByteBuffer): VaultException {
        

        return when(buf.getInt()) {
            1 -> VaultException.Kdf()
            2 -> VaultException.Encrypt()
            3 -> VaultException.Decrypt()
            4 -> VaultException.InvalidSecretKey()
            5 -> VaultException.Malformed()
            6 -> VaultException.InvalidOptions()
            7 -> VaultException.NotFound(
                FfiConverterString.read(buf),
                )
            8 -> VaultException.Io(
                FfiConverterString.read(buf),
                )
            9 -> VaultException.Json(
                FfiConverterString.read(buf),
                )
            else -> throw RuntimeException("invalid error enum value, something is very wrong!!")
        }
    }

    override fun allocationSize(value: VaultException): ULong {
        return when(value) {
            is VaultException.Kdf -> (
                // Add the size for the Int that specifies the variant plus the size needed for all fields
                4UL
            )
            is VaultException.Encrypt -> (
                // Add the size for the Int that specifies the variant plus the size needed for all fields
                4UL
            )
            is VaultException.Decrypt -> (
                // Add the size for the Int that specifies the variant plus the size needed for all fields
                4UL
            )
            is VaultException.InvalidSecretKey -> (
                // Add the size for the Int that specifies the variant plus the size needed for all fields
                4UL
            )
            is VaultException.Malformed -> (
                // Add the size for the Int that specifies the variant plus the size needed for all fields
                4UL
            )
            is VaultException.InvalidOptions -> (
                // Add the size for the Int that specifies the variant plus the size needed for all fields
                4UL
            )
            is VaultException.NotFound -> (
                // Add the size for the Int that specifies the variant plus the size needed for all fields
                4UL
                + FfiConverterString.allocationSize(value.v1)
            )
            is VaultException.Io -> (
                // Add the size for the Int that specifies the variant plus the size needed for all fields
                4UL
                + FfiConverterString.allocationSize(value.v1)
            )
            is VaultException.Json -> (
                // Add the size for the Int that specifies the variant plus the size needed for all fields
                4UL
                + FfiConverterString.allocationSize(value.v1)
            )
        }
    }

    override fun write(value: VaultException, buf: ByteBuffer) {
        when(value) {
            is VaultException.Kdf -> {
                buf.putInt(1)
                Unit
            }
            is VaultException.Encrypt -> {
                buf.putInt(2)
                Unit
            }
            is VaultException.Decrypt -> {
                buf.putInt(3)
                Unit
            }
            is VaultException.InvalidSecretKey -> {
                buf.putInt(4)
                Unit
            }
            is VaultException.Malformed -> {
                buf.putInt(5)
                Unit
            }
            is VaultException.InvalidOptions -> {
                buf.putInt(6)
                Unit
            }
            is VaultException.NotFound -> {
                buf.putInt(7)
                FfiConverterString.write(value.v1, buf)
                Unit
            }
            is VaultException.Io -> {
                buf.putInt(8)
                FfiConverterString.write(value.v1, buf)
                Unit
            }
            is VaultException.Json -> {
                buf.putInt(9)
                FfiConverterString.write(value.v1, buf)
                Unit
            }
        }.let { /* this makes the `when` an expression, which ensures it is exhaustive */ }
    }

}




/**
 * @suppress
 */
public object FfiConverterOptionalString: FfiConverterRustBuffer<kotlin.String?> {
    override fun read(buf: ByteBuffer): kotlin.String? {
        if (buf.get().toInt() == 0) {
            return null
        }
        return FfiConverterString.read(buf)
    }

    override fun allocationSize(value: kotlin.String?): ULong {
        if (value == null) {
            return 1UL
        } else {
            return 1UL + FfiConverterString.allocationSize(value)
        }
    }

    override fun write(value: kotlin.String?, buf: ByteBuffer) {
        if (value == null) {
            buf.put(0)
        } else {
            buf.put(1)
            FfiConverterString.write(value, buf)
        }
    }
}




/**
 * @suppress
 */
public object FfiConverterSequenceTypeItemSummary: FfiConverterRustBuffer<List<ItemSummary>> {
    override fun read(buf: ByteBuffer): List<ItemSummary> {
        val len = buf.getInt()
        return List<ItemSummary>(len) {
            FfiConverterTypeItemSummary.read(buf)
        }
    }

    override fun allocationSize(value: List<ItemSummary>): ULong {
        val sizeForLength = 4UL
        val sizeForItems = value.map { FfiConverterTypeItemSummary.allocationSize(it) }.sum()
        return sizeForLength + sizeForItems
    }

    override fun write(value: List<ItemSummary>, buf: ByteBuffer) {
        buf.putInt(value.size)
        value.iterator().forEach {
            FfiConverterTypeItemSummary.write(it, buf)
        }
    }
}
